"""V12: a diagnostic-first method, with a static accessible four-step pathway."""
import re,html
LANGS=['en','pt-BR','es']
def apply(root,catalog):
 def T(fr,en,pt,es):catalog[fr]=dict(zip(LANGS,[en,pt,es]));return html.escape(fr)
 def P(*v):return '<p>'+T(*v)+'</p>'
 def H(*v,n=2):return f'<h{n}>'+T(*v)+f'</h{n}>'
 def L(*v):return '<li>'+T(*v)+'</li>'
 def CTA():return '<a class="cta-button" href="diagnostic.html">'+T('Et si on étudiait votre cas ?','What if we explored your case?','Que tal estudarmos o seu caso?','¿Y si estudiáramos su caso?')+'</a>'
 hero='<section class="method-intro" id="diagnostic"><div><p class="eyebrow">'+T('Comprendre d’abord. Intervenir avec précision.','Understand first. Intervene precisely.','Entender primeiro. Intervir com precisão.','Comprender primero. Intervenir con precisión.')+'</p>'
 hero+=H('Un diagnostic rapide. Une intervention ciblée. Un existant valorisé.','A rapid diagnosis. A targeted intervention. Existing assets enhanced.','Um diagnóstico rápido. Uma intervenção focada. O existente valorizado.','Un diagnóstico rápido. Una intervención precisa. Lo existente potenciado.',n=1)
 hero+=P('Nous commençons par comprendre vos applications, vos usages et les difficultés de vos équipes. Nous identifions ensuite une amélioration utile et réalisable, avant de vous proposer une intervention précise dans votre écosystème.','We start by understanding your applications, how they are used and your teams’ difficulties. We then identify a useful, achievable improvement before proposing a precise intervention within your ecosystem.','Começamos entendendo seus aplicativos, seus usos e as dificuldades das equipes. Depois identificamos uma melhoria útil e viável, antes de propor uma intervenção precisa no seu ecossistema.','Empezamos por comprender sus aplicaciones, sus usos y las dificultades de sus equipos. Después identificamos una mejora útil y viable antes de proponer una intervención precisa en su ecosistema.')
 hero+='<div class="method-diagnostic-promise"><p class="method-promise">'+T('Un premier diagnostic en quelques jours','An initial diagnosis in a few days','Um primeiro diagnóstico em poucos dias','Un primer diagnóstico en pocos días')+'</p>'
 hero+=P('Sur un périmètre défini, avec les interlocuteurs et les informations nécessaires disponibles. Ce premier regard ciblé permet de préparer des propositions concrètes ; le calendrier de réalisation est ensuite convenu ensemble.','Within a defined scope, with the necessary people and information available. This focused initial assessment prepares concrete proposals; the implementation timeline is then agreed together.','Em um escopo definido, com os interlocutores e as informações necessárias disponíveis. Essa primeira análise focada prepara propostas concretas; o prazo de realização é depois acordado em conjunto.','Sobre un alcance definido, con los interlocutores y la información necesarios disponibles. Esta primera evaluación concreta prepara propuestas; el calendario de realización se acuerda después conjuntamente.')+'</div><div class="actions">'+CTA()+'</div></div>'
 hero+='<aside class="method-deliverables" aria-labelledby="method-deliverables-title"><h2 id="method-deliverables-title">'+T('Ce que vous obtenez','What you receive','O que você recebe','Qué obtiene')+'</h2><ul>'
 for v in [
 ('Une lecture des points de friction et des possibilités de connexion.','An assessment of friction points and connection opportunities.','Uma análise dos pontos de dificuldade e das possibilidades de conexão.','Una evaluación de los puntos de fricción y las posibilidades de conexión.'),
 ('Des propositions d’amélioration classées par priorité.','Improvement proposals ranked by priority.','Propostas de melhoria organizadas por prioridade.','Propuestas de mejora ordenadas por prioridad.'),
 ('Un premier périmètre, un budget et un calendrier proposés.','A proposed initial scope, budget and timeline.','Uma proposta de escopo inicial, orçamento e prazo.','Una propuesta de alcance inicial, presupuesto y calendario.'),
 ('Les gains recherchés et la manière de les mesurer.','The intended benefits and how to measure them.','Os benefícios buscados e como medi-los.','Los beneficios buscados y cómo medirlos.')]:hero+=L(*v)
 hero+='</ul></aside></section>'
 surgery='<section id="intervention" class="method-surgery"><p class="eyebrow">'+T('Une intervention à périmètre maîtrisé','An intervention within a controlled scope','Uma intervenção com escopo controlado','Una intervención de alcance controlado')+'</p>'
 surgery+=H('Une intervention précise, aussi peu invasive que possible.','A precise intervention, as minimally invasive as possible.','Uma intervenção precisa, o menos invasiva possível.','Una intervención precisa, lo menos invasiva posible.')
 surgery+=P('Comme en chirurgie moderne, le diagnostic précède le geste. Notre approche chirurgicale vise un périmètre précis, une intervention rapide et des perturbations minimisées. Nous préservons ce qui fonctionne et limitons les modifications de vos applications à ce qui est nécessaire.','As in modern surgery, diagnosis comes before intervention. Our surgical approach targets a precise scope, rapid action and minimal disruption. We preserve what works and limit changes to your applications to what is necessary.','Como na cirurgia moderna, o diagnóstico vem antes da intervenção. Nossa abordagem cirúrgica busca um escopo preciso, uma intervenção rápida e o mínimo de perturbações. Preservamos o que funciona e limitamos as alterações nos aplicativos ao necessário.','Como en la cirugía moderna, el diagnóstico precede a la intervención. Nuestro enfoque quirúrgico busca un alcance preciso, una actuación rápida y las menores perturbaciones posibles. Preservamos lo que funciona y limitamos los cambios en sus aplicaciones a lo necesario.')
 surgery+='<div class="method-commitments">'
 commitments=[(('Préserver','Preserve','Preservar','Preservar'),('S’appuyer sur vos applications, vos données et les compétences déjà présentes dans vos équipes.','Build on your applications, data and the expertise already present in your teams.','Apoiar-se nos aplicativos, dados e competências já presentes nas equipes.','Apoyarse en sus aplicaciones, datos y competencias ya presentes en sus equipos.')),(('Cibler','Target','Focar','Enfocar'),('Traiter un point de friction identifié en utilisant les connexions et fonctions existantes, avec le minimum d’évolutions nécessaires.','Address an identified friction point using existing connections and features, with the minimum changes required.','Tratar um ponto de dificuldade identificado usando conexões e funções existentes, com o mínimo de mudanças necessárias.','Resolver un punto de fricción identificado utilizando conexiones y funciones existentes, con los mínimos cambios necesarios.')),(('Sécuriser la mise en service','Safeguard go-live','Preparar uma entrada em operação segura','Preparar una puesta en servicio segura'),('Tester le résultat, les exceptions et les conditions d’exploitation ; organiser le déploiement et le retour arrière avant la mise en service.','Test outcomes, exceptions and operating conditions; plan deployment and rollback before go-live.','Testar resultados, exceções e condições de operação; organizar a implantação e o retorno à situação anterior antes da entrada em operação.','Probar resultados, excepciones y condiciones de funcionamiento; organizar el despliegue y la reversión antes de la puesta en servicio.'))]
 for title,copy in commitments:surgery+='<article>'+H(*title,n=3)+P(*copy)+'</article>'
 surgery+='</div></section>'
 process='<section id="pipeline"><p class="eyebrow">'+T('Une démarche courte, des résultats à chaque étape','A focused process, an outcome at each stage','Uma abordagem objetiva, um resultado em cada etapa','Un proceso concreto, un resultado en cada etapa')+'</p>'
 process+=H('Du diagnostic à la mise en service, quatre étapes.','From diagnosis to go-live in four stages.','Do diagnóstico à entrada em operação, quatro etapas.','Del diagnóstico a la puesta en servicio, cuatro etapas.')+'<ol class="method-steps">'
 steps=[(('Diagnostiquer','Diagnose','Diagnosticar','Diagnosticar'),('Comprendre votre situation et identifier les leviers d’amélioration avec les personnes concernées.','Understand your situation and identify improvement opportunities with the people involved.','Entender sua situação e identificar oportunidades de melhoria com as pessoas envolvidas.','Comprender su situación e identificar oportunidades de mejora con las personas implicadas.')),(('Proposer','Propose','Propor','Proponer'),('Choisir ensemble un premier périmètre utile, réalisable et budgété, avec les gains recherchés et leur mesure.','Agree on a useful, achievable and budgeted initial scope, with intended benefits and how to measure them.','Escolher juntos um primeiro escopo útil, viável e orçado, com os benefícios buscados e sua medição.','Elegir juntos un primer alcance útil, viable y presupuestado, con los beneficios buscados y su medición.')),(('Réaliser et tester','Build and test','Desenvolver e testar','Desarrollar y probar'),('Développer rapidement sur le périmètre convenu, puis valider les traitements, les résultats et les exceptions.','Develop rapidly within the agreed scope, then validate processing, results and exceptions.','Desenvolver rapidamente no escopo acordado e validar os processos, os resultados e as exceções.','Desarrollar rápidamente sobre el alcance acordado y validar los tratamientos, resultados y excepciones.')),(('Mettre en service et transmettre','Go live and hand over','Colocar em operação e transmitir','Poner en servicio y transmitir'),('Déployer progressivement, mesurer les résultats et transmettre la documentation pour vous donner les moyens de garder la main.','Deploy progressively, measure results and hand over documentation so you can stay in control.','Implantar gradualmente, medir os resultados e transmitir a documentação para manter o controle nas suas mãos.','Desplegar progresivamente, medir los resultados y transmitir la documentación para que mantenga el control.'))]
 for title,copy in steps:process+='<li>'+H(*title,n=3)+P(*copy)+'</li>'
 process+='</ol><details><summary>'+T('Ce que nous vérifions avant la mise en service','What we check before go-live','O que verificamos antes da entrada em operação','Qué verificamos antes de la puesta en servicio')+'</summary><ul>'
 for v in [
 ('Les sources, les interfaces disponibles et les droits d’accès, avec vos interlocuteurs SI.','Sources, available interfaces and access rights, with your IT contacts.','As fontes, as interfaces disponíveis e os direitos de acesso, com seus interlocutores de TI.','Las fuentes, interfaces disponibles y permisos de acceso, con sus interlocutores de TI.'),
 ('Les rapprochements et enrichissements, les règles métier et le résultat dans chaque application destinataire.','Matching and enrichment, business rules and the outcome in each destination application.','Os cruzamentos e enriquecimentos, as regras de negócio e o resultado em cada aplicativo de destino.','Los cruces y enriquecimientos, las reglas de negocio y el resultado en cada aplicación destinataria.'),
 ('Les exceptions, les contrôles, les traces d’exécution, la reprise en cas d’échec et les conditions de retour arrière.','Exceptions, controls, execution logs, recovery after failure and rollback conditions.','As exceções, os controles, os registros de execução, a retomada em caso de falha e as condições de retorno.','Las excepciones, controles, registros de ejecución, recuperación tras un fallo y condiciones de reversión.')]:process+=L(*v)
 process+='</ul></details><a class="text-link" href="pipelines.html">'+T('Voir nos pipelines en action','See our pipelines in action','Ver nossos pipelines em ação','Ver nuestros pipelines en acción')+'</a></section>'
 ai='<section id="intelligence-artificielle">'+H('L’IA accélère nos développements. Elle enrichit vos pipelines lorsque c’est utile.','AI accelerates our development. It enriches your pipelines where useful.','A IA acelera nossos desenvolvimentos. Ela enriquece seus pipelines quando é útil.','La IA acelera nuestros desarrollos. Enriquece sus pipelines cuando resulta útil.')+'<div class="method-ai">'
 ai+='<article>'+H('Pour construire plus rapidement','To build faster','Para desenvolver mais rapidamente','Para desarrollar más rápido',n=3)
 ai+=P('Nous utilisons intensivement l’IA pour assister l’analyse, l’écriture du code, les tests et la documentation. Cet appui accélère les développements et nous permet de nous adapter à votre environnement technologique. Les choix techniques et les réalisations restent revus, testés et validés.','We make extensive use of AI to assist analysis, coding, testing and documentation. It accelerates development while adapting to your technology environment. Technical choices and deliverables remain subject to review, testing and validation.','Usamos intensivamente a IA para apoiar a análise, a escrita do código, os testes e a documentação. Ela acelera os desenvolvimentos, adaptando-nos ao seu ambiente tecnológico. As escolhas técnicas e as entregas continuam sendo revisadas, testadas e validadas.','Utilizamos intensivamente la IA para apoyar el análisis, la escritura del código, las pruebas y la documentación. Acelera los desarrollos adaptándonos a su entorno tecnológico. Las decisiones técnicas y los desarrollos siguen siendo revisados, probados y validados.')+'</article>'
 ai+='<article>'+H('Dans vos pipelines, si elle apporte une valeur utile','Inside your pipelines, when it adds useful value','Nos seus pipelines, quando agrega valor útil','En sus pipelines, si aporta valor útil',n=3)
 ai+=P('Selon le besoin, un pipeline peut intégrer de l’IA pour analyser des documents, extraire des informations, classer des contenus ou préparer une synthèse. Son usage est choisi avec vous et accompagné de contrôles adaptés, notamment sur la qualité des résultats et la validation humaine nécessaire.','Depending on the need, a pipeline can incorporate AI to analyse documents, extract information, classify content or prepare a summary. Its use is agreed with you and supported by appropriate controls, especially on result quality and any human validation required.','Conforme a necessidade, um pipeline pode integrar IA para analisar documentos, extrair informações, classificar conteúdos ou preparar uma síntese. Seu uso é escolhido com você e acompanhado de controles adequados, sobretudo quanto à qualidade dos resultados e à validação humana necessária.','Según la necesidad, un pipeline puede integrar IA para analizar documentos, extraer información, clasificar contenidos o preparar una síntesis. Su uso se decide con usted y se acompaña de controles adecuados, especialmente sobre la calidad de los resultados y la validación humana necesaria.')+'</article></div>'
 ai+=P('Les conditions de confidentialité, les droits d’accès et les contraintes de votre SI sont vérifiés avec vos interlocuteurs avant de retenir les outils et les usages de l’IA.','Confidentiality requirements, access rights and your IT constraints are reviewed with your contacts before selecting AI tools and uses.','As condições de confidencialidade, os direitos de acesso e as restrições do seu ambiente de TI são verificados com seus interlocutores antes de escolher as ferramentas e os usos da IA.','Las condiciones de confidencialidad, los permisos de acceso y las restricciones de su SI se revisan con sus interlocutores antes de elegir las herramientas y los usos de la IA.')+'</section>'
 budget='<section id="remuneration" class="method-budget">'+H('Un premier investissement limité pour engager les premiers gains rapidement.','A limited initial investment to start generating benefits sooner.','Um investimento inicial limitado para começar a gerar benefícios rapidamente.','Una inversión inicial limitada para empezar a generar beneficios pronto.')
 budget+=P('Le réemploi de vos outils, un périmètre initial réduit, des développements accélérés par l’IA et une mise en service progressive concentrent l’investissement sur l’amélioration utile. Le budget, la durée et les gains attendus sont évalués pour votre périmètre avant réalisation.','Reusing your tools, limiting the initial scope, accelerating development with AI and going live progressively focus investment on useful improvements. Budget, duration and expected benefits are assessed for your scope before implementation.','O reaproveitamento das ferramentas, um escopo inicial reduzido, desenvolvimentos acelerados pela IA e uma entrada em operação gradual concentram o investimento na melhoria útil. Orçamento, prazo e benefícios esperados são avaliados para seu escopo antes da realização.','Reutilizar sus herramientas, reducir el alcance inicial, acelerar el desarrollo con IA y poner en servicio progresivamente concentran la inversión en la mejora útil. Presupuesto, duración y beneficios esperados se evalúan para su alcance antes de la realización.')
 budget+=P('Notre objectif est un bénéfice durable et votre autonomie. Nous ne cherchons pas à installer une facturation récurrente. Selon le projet, une rémunération liée aux bénéfices effectivement constatés peut être convenue avant l’intervention.','Our aim is lasting benefits and your autonomy. We do not seek to establish recurring billing. Depending on the project, remuneration linked to benefits actually observed may be agreed before work begins.','Nosso objetivo é um benefício duradouro e sua autonomia. Não buscamos estabelecer cobranças recorrentes. Conforme o projeto, pode ser acordada antes da intervenção uma remuneração ligada aos benefícios efetivamente constatados.','Nuestro objetivo es un beneficio duradero y su autonomía. No buscamos establecer una facturación recurrente. Según el proyecto, puede acordarse antes de la intervención una remuneración vinculada a los beneficios efectivamente constatados.')
 budget+='<details><summary>'+T('Comment nous cadrons les coûts et la mesure des bénéfices','How we define costs and measure benefits','Como definimos os custos e medimos os benefícios','Cómo definimos los costes y medimos los beneficios')+'</summary>'
 budget+=P('Nous convenons des indicateurs, de la situation de départ, de la période de mesure et de la manière de constater les résultats. Les modalités de calcul et de paiement sont définies dans l’accord commercial, y compris si les résultats sont inférieurs aux attentes.','We agree on indicators, the baseline, the measurement period and how results will be established. Calculation and payment terms are defined in the commercial agreement, including if results fall below expectations.','Acordamos os indicadores, a situação inicial, o período de medição e a forma de verificar os resultados. As condições de cálculo e pagamento são definidas no acordo comercial, inclusive se os resultados ficarem abaixo do esperado.','Acordamos los indicadores, la situación inicial, el período de medición y la forma de constatar los resultados. Las condiciones de cálculo y pago se definen en el acuerdo comercial, también si los resultados son inferiores a lo esperado.')
 budget+=P('Du temps libéré n’est pas automatiquement une économie financière. Les coûts éventuels de logiciels ou d’hébergement sont identifiés séparément. Un besoin de suivi ultérieur fait l’objet d’un accord distinct.','Time freed up is not automatically a financial saving. Any software or hosting costs are identified separately. Subsequent support is covered by a separate agreement.','O tempo liberado não é automaticamente uma economia financeira. Eventuais custos de software ou hospedagem são identificados separadamente. Acompanhamento posterior é objeto de um acordo específico.','El tiempo liberado no supone automáticamente un ahorro financiero. Los posibles costes de software o alojamiento se identifican por separado. Un seguimiento posterior se acuerda de forma específica.')+'</details></section>'
 faq='<section id="questions-pratiques">'+H('Vos questions pratiques','Practical questions','Suas perguntas práticas','Sus preguntas prácticas')
 for title,copy in [
 (('Faut-il remplacer nos outils ?','Do we need to replace our tools?','É preciso substituir nossas ferramentas?','¿Hay que sustituir nuestras herramientas?'),('Notre priorité est de valoriser vos applications existantes et leurs interfaces. Une évolution ou un remplacement peut rester nécessaire : sa pertinence et son impact sont examinés pendant le diagnostic et convenus avec vous.','Our priority is to build on your existing applications and interfaces. A change or replacement may still be necessary: its relevance and impact are assessed during diagnosis and agreed with you.','Nossa prioridade é valorizar os aplicativos e interfaces existentes. Uma evolução ou substituição pode continuar necessária: sua pertinência e impacto são analisados no diagnóstico e acordados com você.','Nuestra prioridad es aprovechar sus aplicaciones e interfaces existentes. Puede seguir siendo necesario un cambio o una sustitución: su pertinencia e impacto se analizan durante el diagnóstico y se acuerdan con usted.')),
 (('Qui doit participer au diagnostic ?','Who should take part in the diagnosis?','Quem deve participar do diagnóstico?','¿Quién debe participar en el diagnóstico?'),('Les personnes qui réalisent le travail, un responsable du périmètre et, selon les sujets, les interlocuteurs informatiques. Nous organisons ensemble leur disponibilité et l’accès aux informations nécessaires.','The people doing the work, someone responsible for the scope and, depending on the topic, IT contacts. Together we organise their availability and access to the necessary information.','As pessoas que realizam o trabalho, um responsável pelo escopo e, conforme o assunto, interlocutores de TI. Organizamos juntos sua disponibilidade e o acesso às informações necessárias.','Las personas que realizan el trabajo, un responsable del alcance y, según el tema, los interlocutores informáticos. Organizamos juntos su disponibilidad y el acceso a la información necesaria.'))]:faq+='<details><summary>'+T(*title)+'</summary>'+P(*copy)+'</details>'
 faq+='<div class="method-final-cta">'+H('Commençons par comprendre votre situation.','Let’s start by understanding your situation.','Vamos começar entendendo sua situação.','Empecemos por comprender su situación.',n=3)+'<div class="actions">'+CTA()+'</div></div></section>'
 path=root/'approche.html';s=path.read_text()
 s=re.sub(r'<main\b[^>]*>.*?</main>','<main id="main-content">'+hero+surgery+process+ai+budget+faq+'</main>',s,flags=re.S)
 s=re.sub(r'<body[^>]*>','<body class="method-page">',s,count=1)
 title=T('Diagnostic rapide et intervention ciblée — CLN Performance','Rapid diagnosis and targeted intervention — CLN Performance','Diagnóstico rápido e intervenção focada — CLN Performance','Diagnóstico rápido e intervención precisa — CLN Performance')
 desc=T('Un premier diagnostic ciblé en quelques jours, des propositions concrètes et une intervention peu invasive pour valoriser vos applications. IA, coûts maîtrisés et autonomie.','A focused initial diagnosis in a few days, concrete proposals and a minimally invasive intervention to enhance your applications. AI, controlled costs and autonomy.','Um diagnóstico inicial focado em poucos dias, propostas concretas e uma intervenção pouco invasiva para valorizar seus aplicativos. IA, custos controlados e autonomia.','Un primer diagnóstico concreto en pocos días, propuestas y una intervención poco invasiva para potenciar sus aplicaciones. IA, costes controlados y autonomía.')
 s=re.sub(r'<title>.*?</title>','<title>'+title+'</title>',s,flags=re.S)
 s=re.sub(r'<meta name="description" content="[^"]*"\s*/?>','<meta name="description" content="'+desc+'" />',s)
 s=re.sub(r'\?v=20261030-v\d+(?:r\d+)?','?v=20261030-v12',s)
 path.write_text(re.sub(r'>\s*<','>\n<',s))
